KATHMANDU, NEPAL 09.01.2026 Photo by Senior Airman Cayla Hunt Pacific Air Forces ✔ ✗ Subscribe 38 if (quickSubscribeIncluded == undefined) { var quickSubscribeIncluded = true; // only include this code ONCE per page $(document).ready(function() { function toggleSubscribed(data) { if (data.loggedIn === true) { $.getJSON('/alerts/checksubscribe', {'searchTerm': '557', 'searchType': 'unit'}, function(data, textStatus, xhr) { if (data.count === 0) { $('.subscribe-text').text('Subscribe'); } else { $('.subscribe-text').text('Subscribed'); } }); } else { $('.subscribe-text').text('Subscribe'); } } $(document).bind(dvids.auth.events.query, function(event, data) { toggleSubscribed(data); }); $(document).bind(dvids.auth.events.loginSuccess, function(event, data) { toggleSubscribed(data); }); $(document).bind(dvids.auth.events.logout, function(event, data) { $('.subscribe-text').text('Subscribe'); }); $("a.newswire-subscribe").click(function(event) { event.preventDefault(); var element = $(this); var searchTerm = element.attr("id"); var searchType = element.attr("alert_type"); var href = element.attr("href"); var subscribed = parseInt(element.siblings('div.subscribed-count').html()); $.ajax({ type: "POST", url: "/alerts/quicksubscribe", context: this, data: { searchTerm: searchTerm, searchType: searchType, }, success: function(data) { if (data == "please login") { window.location.href = href; } else if (data.result == "error") { UIkit.notify(data.message, {status:'danger', timeout : 0}); } else if (data.result == "success" && data.message == "unsubscribed") { element.removeClass("subscribed").removeClass("unsubscribe"); element.find("span.subscribe-text").html("Subscribe"); element.siblings('div.subscribed-count').html(subscribed - 1); element.find("span.bell").show(); element.find("span.checkmark, span.x").hide(); } else if (data.result == "success" && data.message == "subscribed") { element.addClass("subscribed"); element.find("span.subscribe-text").html("Subscribed"); element.siblings('div.subscribed-count').html(subscribed + 1); element.find("span.bell").hide(); element.find("span.checkmark").show(); } } }); }); $(document).on("mouseenter", "a.newswire-subscribe.subscribed", function(event) { $(this).addClass("unsubscribe"); $(this).find("span.subscribe-text").html("Unsubscribe"); $(this).find("span.x").show(); $(this).find("span.checkmark").hide(); }); $(document).on("mouseleave", "a.newswire-subscribe.subscribed", function(event) { $(this).removeClass("unsubscribe"); $(this).find("span.subscribe-text").html("Subscribed"); $(this).find("span.x").hide(); $(this).find("span.checkmark").show(); }); }); }

U.S. Air Force Maj. Preston Edwards, a pilot assigned to the 36th Airlift Squadron, speaks with U.S. Embassy Nepal Chargé d’Affaires Scott Urbom at Tribhuvan International Airport, Nepal, Sept. 2, 2026, following the delivery of life-saving supplies. The mission to provide life saving assistance reflects the United States' unwavering commitment to stand in solidarity with the people of Nepal and support locally led recovery operations. (U.S. Air Force photo by Senior Airman Cayla Hunt)
